'use client';

import { SearchPage } from '@/components/search/search-page';
import type { SearchFilters, SearchResponse } from '@/lib/contracts';
import { mockEmptySearchResponse, mockFilterOptions, mockSearchResponse } from '@/mocks/search';
import { EMPTY_FILTERS } from '@/lib/search-query';

let n = 0;
async function fetchResults(f: SearchFilters): Promise<SearchResponse> {
  n++;
  (window as unknown as { __calls: unknown[] }).__calls ??= [];
  (window as unknown as { __calls: unknown[] }).__calls.push(f);
  // Older requests take longer, so stale responses would land last.
  const delay = n % 2 === 1 ? 1500 : 500;
  await new Promise((r) => setTimeout(r, delay));
  if (f.skills.includes('Rust')) throw new Error('boom');
  if (f.countries.includes('India')) return { ...mockEmptySearchResponse, filters: f };
  return { ...mockSearchResponse, filters: f };
}

export default function Preview() {
  return (
    <SearchPage options={mockFilterOptions} initialFilters={EMPTY_FILTERS} fetchResults={fetchResults} />
  );
}

