const byLabel = (t) => { const l = [...document.querySelectorAll('label')].find(l => l.textContent === t); return document.getElementById(l.htmlFor); };
const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
const type = (el, v) => { setter.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
const before = window.__calls.length;
type(byLabel('Max salary (USD/yr)'), '120000');
type(byLabel('Min salary (USD/yr)'), '60000');
type(byLabel('Min years'), '5');
await sleep(400);
const r = { url: location.search, calls: window.__calls.slice(before) };
type(byLabel('Min years'), '');
await sleep(10);
r.url2 = location.search;
r

